/**
 * The engine's end-to-end-encryption device identity for one account, sealed at rest.
 *
 * To receive the cloud key from the phone, the engine must be a registered end-to-end-encryption device: it holds a
 * Signal identity (identity key pair, registration id, a signed pre-key and one-time pre-keys) and publishes the public
 * half so the phone can encrypt to it. That identity is generated by the protocol layer (src/zalo/e2ee) and its store is
 * sealed here, under the account's data key, in `accounts/<ownId>/e2ee-device.json` — a new sealed per-account file (it
 * is NOT a writer to `zalo.db`, so the three-writers rule is untouched).
 *
 * The file records which platform slot the device claims (MOBILE 0 / WEB 1 / PC 2): there is one bundle per slot, and
 * this engine announces the web platform, so it would claim WEB by default — the slot a real web-platform device (such
 * as the owner's browser session) uses. The slot is stored so the device-list check and the re-submit can reason about
 * it.
 *
 * SECRETS: the Signal private keys are written only sealed (0600, data key). Nothing here logs or prints a key;
 * {@link e2eeDeviceStatus} returns metadata only.
 */
import { existsSync, rmSync } from "node:fs";
import { join } from "node:path";
import { getAccountDir } from "./credentials.js";
import { openFile, scopeOf, sealFile } from "./keystore/index.js";
import { DEVICE_IDS, platformName } from "../zalo/e2ee/bundle-wire.js";
import { SignalProtocolStore } from "../zalo/e2ee/signal-store.js";
import { bundleFromStore, generateDeviceIdentity, generateOneTimePreKeys } from "../zalo/e2ee/identity.js";

const SPEC = { kind: "e2ee-device", use: "data" };

/**
 * Where an account's sealed device identity lives.
 *
 * @param {string} ownId
 * @returns {string}
 */
export function e2eeDeviceFile(ownId) {
    return join(getAccountDir(String(ownId)), "e2ee-device.json");
}

/**
 * Whether an account has a stored end-to-end-encryption device (does not open it).
 *
 * @param {string} ownId
 * @returns {boolean}
 */
export function hasE2eeDevice(ownId) {
    return existsSync(e2eeDeviceFile(ownId));
}

/**
 * Load the stored device identity, rebuilding its Signal store, or null when there is none.
 *
 * @param {string} ownId
 * @returns {{store: SignalProtocolStore, deviceId: number, registrationId: number, signedPreKeyId: number,
 *   createdAt: number, submittedAt: number|null}|null}
 * @throws {Error} a KeystoreError when the file is there but its key is locked
 */
export function loadE2eeDevice(ownId) {
    const bytes = openFile(e2eeDeviceFile(ownId), scopeOf(String(ownId)), SPEC);
    if (bytes === null) return null;
    const parsed = JSON.parse(bytes.toString("utf8"));
    if (!parsed?.store) return null;
    return {
        store: SignalProtocolStore.fromJSON(parsed.store),
        deviceId: Number(parsed.deviceId),
        registrationId: Number(parsed.registrationId),
        signedPreKeyId: Number(parsed.signedPreKeyId),
        createdAt: parsed.createdAt ?? null,
        submittedAt: parsed.submittedAt ?? null,
    };
}

/**
 * Seal and store a device identity.
 *
 * @param {string} ownId
 * @param {{store: SignalProtocolStore, deviceId: number, registrationId: number, signedPreKeyId: number,
 *   createdAt?: number, submittedAt?: number|null}} record
 */
export function saveE2eeDevice(ownId, record) {
    sealFile(
        e2eeDeviceFile(ownId),
        scopeOf(String(ownId)),
        SPEC,
        JSON.stringify({
            store: record.store.toJSON(),
            deviceId: Number(record.deviceId),
            registrationId: Number(record.registrationId),
            signedPreKeyId: Number(record.signedPreKeyId),
            createdAt: record.createdAt ?? Date.now(),
            submittedAt: record.submittedAt ?? null,
        }),
    );
}

/**
 * Generate a fresh device identity, seal it, and return it with the public bundle to publish. Offline: it registers
 * nothing with Zalo (publishing is a separate, gated live step).
 *
 * @param {string} ownId
 * @param {object} [opts]
 * @param {number} [opts.deviceId] - the platform slot to claim (default WEB)
 * @param {number} [opts.preKeyCount]
 * @returns {Promise<{record: object, bundle: object}>}
 */
export async function createE2eeDevice(ownId, { deviceId = DEVICE_IDS.WEB, preKeyCount } = {}) {
    const gen = await generateDeviceIdentity(preKeyCount === undefined ? {} : { preKeyCount });
    const record = {
        store: gen.store,
        deviceId: Number(deviceId),
        registrationId: gen.registrationId,
        signedPreKeyId: gen.signedPreKeyId,
        createdAt: Date.now(),
        submittedAt: null,
    };
    saveE2eeDevice(ownId, record);
    return { record, bundle: bundleFromStore(gen.store) };
}

/**
 * Replenish a device's one-time pre-keys and re-seal it; returns the new ids and the fresh public pre-keys to publish.
 *
 * @param {string} ownId
 * @param {object} [opts]
 * @param {number} [opts.count]
 * @returns {Promise<{ids: number[], preKeys: Array<{keyId: number, publicKey: string}>}>}
 */
export async function replenishPreKeys(ownId, { count } = {}) {
    const device = loadE2eeDevice(ownId);
    if (!device) throw new Error("no end-to-end-encryption device is stored for this account");
    const ids = await generateOneTimePreKeys(device.store, count === undefined ? {} : { count });
    saveE2eeDevice(ownId, device);
    const bundle = bundleFromStore(device.store);
    return { ids, preKeys: bundle.preKeys.filter((k) => ids.includes(k.keyId)) };
}

/**
 * Mark the device as published (its bundle submitted), for status display.
 *
 * @param {string} ownId
 * @param {() => number} [now]
 */
export function markE2eeDeviceSubmitted(ownId, now = Date.now) {
    const device = loadE2eeDevice(ownId);
    if (!device) return;
    saveE2eeDevice(ownId, { ...device, submittedAt: now() });
}

/**
 * Delete the stored device identity.
 *
 * @param {string} ownId
 * @returns {boolean} whether a file was removed
 */
export function forgetE2eeDevice(ownId) {
    const file = e2eeDeviceFile(ownId);
    if (!existsSync(file)) return false;
    rmSync(file, { force: true });
    return true;
}

/**
 * The device's status for `cloud key status`: metadata only, never a key byte.
 *
 * @param {string} ownId
 * @returns {{registered: boolean, deviceId: number|null, platform: string|null, registrationId: number|null,
 *   preKeyCount: number|null, createdAt: number|null, submittedAt: number|null, locked: boolean, file: string}}
 */
export function e2eeDeviceStatus(ownId) {
    const file = e2eeDeviceFile(ownId);
    if (!existsSync(file)) {
        return {
            registered: false,
            deviceId: null,
            platform: null,
            registrationId: null,
            preKeyCount: null,
            createdAt: null,
            submittedAt: null,
            locked: false,
            file,
        };
    }
    try {
        const device = loadE2eeDevice(ownId);
        return {
            registered: Boolean(device),
            deviceId: device?.deviceId ?? null,
            platform: device ? platformName(device.deviceId) : null,
            registrationId: device?.registrationId ?? null,
            preKeyCount: device?.store.preKeyCount() ?? null,
            createdAt: device?.createdAt ?? null,
            submittedAt: device?.submittedAt ?? null,
            locked: false,
            file,
        };
    } catch {
        return {
            registered: true,
            deviceId: null,
            platform: null,
            registrationId: null,
            preKeyCount: null,
            createdAt: null,
            submittedAt: null,
            locked: true,
            file,
        };
    }
}
